use crate::{ConfigError, MicrosecondsPrecisionOverflowBehavior};
use core::str::FromStr;

#[derive(Debug, Clone, Copy, Default, PartialEq)]
pub enum TimestampUnit {
    /// Interpret as seconds since the UNIX epoch.
    Second,
    /// Interpret as milliseconds since the UNIX epoch.
    Millisecond,
    /// Let the parser infer units based on value length.
    #[default]
    Infer,
}

impl FromStr for TimestampUnit {
    type Err = ConfigError;
    fn from_str(value: &str) -> Result<Self, ConfigError> {
        if value.eq_ignore_ascii_case("s") {
            Ok(Self::Second)
        } else if value.eq_ignore_ascii_case("ms") {
            Ok(Self::Millisecond)
        } else if value.eq_ignore_ascii_case("infer") {
            Ok(Self::Infer)
        } else {
            Err(ConfigError::UnknownTimestampUnitString)
        }
    }
}
